package com.jadhavr.erp.staff.controller;
import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.common.dto.PageResponse; import com.jadhavr.erp.staff.dto.StaffResponse; import com.jadhavr.erp.staff.enums.*; import com.jadhavr.erp.staff.service.StaffService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/super-admin/staff") public class SuperAdminStaffController {private final StaffService service;public SuperAdminStaffController(StaffService s){service=s;}@GetMapping({"","/search"})public ApiResponse<PageResponse<StaffResponse>> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)StaffType staffType,@RequestParam(required=false)StaffStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ApiResponse.success("Staff retrieved",service.searchStaff(keyword,collegeId,staffType,status,page,size,"createdAt","desc"));}@GetMapping("/{id}")public ApiResponse<StaffResponse>get(@PathVariable Long id){return ApiResponse.success("Staff retrieved",service.getStaffById(id));}}
